default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Securepipeservers\Winreg\Allowedpaths' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('Machine', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [string[]] -and $current.Length -eq 11 -and [string]::Join([string][char]0, $current) -ceq [string]::Join([string][char]0, @('System\CurrentControlSet\Control\Print\Printers', 'System\CurrentControlSet\Services\Eventlog', 'Software\Microsoft\OLAP Server', 'Software\Microsoft\Windows NT\CurrentVersion\Print', 'Software\Microsoft\Windows NT\CurrentVersion\Windows', 'System\CurrentControlSet\Control\ContentIndex', 'System\CurrentControlSet\Control\Terminal Server', 'System\CurrentControlSet\Control\Terminal Server\UserConfig', 'System\CurrentControlSet\Control\Terminal Server\DefaultUserConfiguration', 'Software\Microsoft\Windows NT\CurrentVersion\Perflib', 'System\CurrentControlSet\Services\SysmonLog')))) {
    Write-Output 'Mismatch: HKLM:\System\Currentcontrolset\Control\Securepipeservers\Winreg\Allowedpaths [Machine]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Securepipeservers\Winreg\Allowedpaths')) {
    New-Item -Path 'HKLM:\System\Currentcontrolset\Control\Securepipeservers\Winreg\Allowedpaths' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Securepipeservers\Winreg\Allowedpaths' -Name 'Machine' -Value @('System\CurrentControlSet\Control\Print\Printers', 'System\CurrentControlSet\Services\Eventlog', 'Software\Microsoft\OLAP Server', 'Software\Microsoft\Windows NT\CurrentVersion\Print', 'Software\Microsoft\Windows NT\CurrentVersion\Windows', 'System\CurrentControlSet\Control\ContentIndex', 'System\CurrentControlSet\Control\Terminal Server', 'System\CurrentControlSet\Control\Terminal Server\UserConfig', 'System\CurrentControlSet\Control\Terminal Server\DefaultUserConfiguration', 'Software\Microsoft\Windows NT\CurrentVersion\Perflib', 'System\CurrentControlSet\Services\SysmonLog') -PropertyType MultiString -Force | Out-Null
exit 0
